import subprocess, json, os, tempfile

def handle(query, state):
    filename = (query.get("file") or [""])[0]
    if not filename:
        return 400, {"Content-Type": "text/plain"}, "error: file parameter required"

    flag = state.get("flag", "")
    flag_file = os.path.join(tempfile.gettempdir(), "flag_db.json")
    with open(flag_file, "w") as f:
        json.dump({"secret": flag}, f)

    try:
        result = subprocess.run(
            f"ls -la {filename}",
            shell=True,
            capture_output=True,
            text=True,
            timeout=5
        )
        output = result.stdout if result.stdout else result.stderr
        return 200, {"Content-Type": "text/plain"}, output
    except subprocess.TimeoutExpired:
        return 500, {"Content-Type": "text/plain"}, "error: command timeout"
    except Exception as e:
        return 500, {"Content-Type": "text/plain"}, "error: " + str(e)
